function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const {
    collectSalesData,
    classifySalesDataByProduct,
    classifySalesDataByStore,
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.businessLogic || {};

  // 計算結果を格納する配列
  let calculationResults = [];

  // 店舗データを取得してセレクトボックスに設定
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1);
      const storeSelect = container.querySelector('#select-store');
      if (storeSelect) {
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';

        if (stores) {
          stores.forEach(store => {
            const option = document.createElement('option');
            option.value = store.id;
            option.textContent = `${store.店舗名} (${store.店舗コード})`;
            storeSelect.appendChild(option);
          });
        }
      }
    } catch (error) {
      window.aivicNotify.error('店舗データの取得に失敗しました');
    }
  }

  // 商品データを取得してセレクトボックスに設定
  async function loadProducts() {
    try {
      const products = await window.aivicApi.list(2);
      const productSelect = container.querySelector('#select-product');
      if (productSelect) {
        productSelect.innerHTML = '<option value="">商品を選択してください</option>';

        if (products) {
          products.forEach(product => {
            const option = document.createElement('option');
            option.value = product.id;
            option.textContent = `${product.商品名} (${product.商品コード})`;
            productSelect.appendChild(option);
          });
        }
      }
    } catch (error) {
      window.aivicNotify.error('商品データの取得に失敗しました');
    }
  }

  // 発注量計算処理
  async function calculateOrderQuantity() {
    try {
      const storeSelect = container.querySelector('#select-store');
      const productSelect = container.querySelector('#select-product');
      const startDateInput = container.querySelector('#start-date');
      const endDateInput = container.querySelector('#end-date');

      if (!storeSelect || !productSelect || !startDateInput || !endDateInput) {
        window.aivicNotify.error('必要な入力項目が見つかりません');
        return;
      }

      const storeId = storeSelect.value;
      const productId = productSelect.value;
      const startDate = startDateInput.value;
      const endDate = endDateInput.value;

      if (!storeId || !productId || !startDate || !endDate) {
        window.aivicNotify.error('すべての項目を入力してください');
        return;
      }

      // 計算中表示
      const calculateBtn = container.querySelector('#btn-calculate');
      if (calculateBtn) {
        calculateBtn.disabled = true;
        calculateBtn.textContent = '計算中...';
      }

      try {
        // 売上データ収集
        const salesData = await collectSalesData(storeId, productId, startDate, endDate);

        // 商品別・店舗別データ分類
        const productClassifiedData = classifySalesDataByProduct(salesData);
        const storeClassifiedData = classifySalesDataByStore(salesData);

        // 有効な商品データのフィルタリング
        const validProductData = filterValidProductData(productClassifiedData);

        // 外部データ収集
        const weatherData = await collectWeatherData(startDate, endDate);
        const eventData = await collectEventData(startDate, endDate);
        const seasonalData = await collectSeasonalData(startDate, endDate);

        // 相関分析
        const weatherCorrelation = analyzeCorrelationSalesWeather(validProductData, weatherData);
        const eventCorrelation = analyzeCorrelationSalesEvent(validProductData, eventData);
        const seasonalCorrelation = analyzeCorrelationSalesSeason(validProductData, seasonalData);

        // 過去データとの比較
        const historicalComparison = compareWithHistoricalData(validProductData, storeId, productId);

        // 代替比較データの検索
        const alternativeData = findAlternativeComparisonData(validProductData, storeId, productId);

        // 比較期間の妥当性検証
        const periodValidation = validateComparisonPeriod(startDate, endDate);

        // 計算結果の統合
        const calculationResult = {
          storeId,
          productId,
          period: { startDate, endDate },
          salesData: validProductData,
          correlations: {
            weather: weatherCorrelation,
            event: eventCorrelation,
            seasonal: seasonalCorrelation
          },
          historicalComparison,
          alternativeData,
          periodValidation,
          calculatedAt: new Date().toISOString()
        };

        // 結果を配列に追加
        calculationResults.push(calculationResult);

        // 結果テーブルの更新
        updateResultsTable();

        window.aivicNotify.success('発注量計算が完了しました');

      } catch (error) {
        console.error('計算処理エラー:', error);
        window.aivicNotify.error('計算処理中にエラーが発生しました: ' + error.message);
      } finally {
        // ボタンを元に戻す
        if (calculateBtn) {
          calculateBtn.disabled = false;
          calculateBtn.textContent = '計算実行';
        }
      }

    } catch (error) {
      console.error('発注量計算エラー:', error);
      window.aivicNotify.error('発注量計算に失敗しました');
    }
  }

  // 結果テーブルの更新
  function updateResultsTable() {
    const resultsTable = container.querySelector('#results-table tbody');
    if (!resultsTable) return;

    resultsTable.innerHTML = '';

    calculationResults.forEach((result, index) => {
      const row = document.createElement('tr');

      // 店舗名取得
      const storeSelect = container.querySelector('#select-store');
      const storeOption = storeSelect?.querySelector(`option[value="${result.storeId}"]`);
      const storeName = storeOption?.textContent || result.storeId;

      // 商品名取得
      const productSelect = container.querySelector('#select-product');
      const productOption = productSelect?.querySelector(`option[value="${result.productId}"]`);
      const productName = productOption?.textContent || result.productId;

      row.innerHTML = `
        <td>${storeName}</td>
        <td>${productName}</td>
        <td>${result.period.startDate} ～ ${result.period.endDate}</td>
        <td>${result.correlations.weather?.correlation || 'N/A'}</td>
        <td>${result.correlations.event?.correlation || 'N/A'}</td>
        <td>${result.correlations.seasonal?.correlation || 'N/A'}</td>
        <td>${new Date(result.calculatedAt).toLocaleString()}</td>
        <td>
          <button class="btn btn-sm btn-info" onclick="viewDetail(${index})">詳細</button>
          <button class="btn btn-sm btn-danger" onclick="deleteResult(${index})">削除</button>
        </td>
      `;

      resultsTable.appendChild(row);
    });
  }

  // 結果詳細表示
  window.viewDetail = function(index) {
    const result = calculationResults[index];
    if (!result) return;

    const detailModal = container.querySelector('#detail-modal');
    const detailContent = container.querySelector('#detail-content');

    if (detailModal && detailContent) {
      detailContent.innerHTML = `
        <h5>計算結果詳細</h5>
        <div class="row">
          <div class="col-md-6">
            <h6>基本情報</h6>
            <p><strong>店舗ID:</strong> ${result.storeId}</p>
            <p><strong>商品ID:</strong> ${result.productId}</p>
            <p><strong>期間:</strong> ${result.period.startDate} ～ ${result.period.endDate}</p>
          </div>
          <div class="col-md-6">
            <h6>相関分析結果</h6>
            <p><strong>天候相関:</strong> ${JSON.stringify(result.correlations.weather, null, 2)}</p>
            <p><strong>イベント相関:</strong> ${JSON.stringify(result.correlations.event, null, 2)}</p>
            <p><strong>季節相関:</strong> ${JSON.stringify(result.correlations.seasonal, null, 2)}</p>
          </div>
        </div>
        <div class="row">
          <div class="col-12">
            <h6>過去データ比較</h6>
            <pre>${JSON.stringify(result.historicalComparison, null, 2)}</pre>
          </div>
        </div>
      `;

      detailModal.style.display = 'block';
    }
  };

  // 結果削除
  window.deleteResult = function(index) {
    if (confirm('この計算結果を削除しますか？')) {
      calculationResults.splice(index, 1);
      updateResultsTable();
      window.aivicNotify.success('計算結果を削除しました');
    }
  };

  // 結果クリア
  function clearResults() {
    if (confirm('すべての計算結果をクリアしますか？')) {
      calculationResults = [];
      updateResultsTable();
      window.aivicNotify.success('計算結果をクリアしました');
    }
  }

  // 結果エクスポート
  function exportResults() {
    if (calculationResults.length === 0) {
      window.aivicNotify.error('エクスポートする結果がありません');
      return;
    }

    const dataStr = JSON.stringify(calculationResults, null, 2);
    const dataBlob = new Blob([dataStr], {type: 'application/json'});
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `order_calculation_results_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);

    window.aivicNotify.success('計算結果をエクスポートしました');
  }

  // イベントハンドラーの設定
  function setupEventHandlers() {
    // 計算実行ボタン
    const calculateBtn = container.querySelector('#btn-calculate');
    if (calculateBtn) {
      calculateBtn.addEventListener('click', calculateOrderQuantity);
    }

    // 結果クリアボタン
    const clearBtn = container.querySelector('#btn-clear-results');
    if (clearBtn) {
      clearBtn.addEventListener('click', clearResults);
    }

    // エクスポートボタン
    const exportBtn = container.querySelector('#btn-export-results');
    if (exportBtn) {
      exportBtn.addEventListener('click', exportResults);
    }

    // モーダル閉じるボタン
    const closeModalBtn = container.querySelector('#close-modal');
    if (closeModalBtn) {
      closeModalBtn.addEventListener('click', () => {
        const detailModal = container.querySelector('#detail-modal');
        if (detailModal) {
          detailModal.style.display = 'none';
        }
      });
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      await loadProducts();
      setupEventHandlers();
      updateResultsTable();
    } catch (error) {
      console.error('初期化エラー:', error);
      window.aivicNotify.error('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
